import{World}from '../world.js';import fs from 'node:fs';import assert from 'node:assert/strict';
export const source=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
export function flow(){let dialog;const w=new World(source,{onDialog:d=>dialog=d});const finish=()=>{for(let n=0;dialog&&!dialog.choices&&n<30;n++){const d=dialog;dialog=null;d.after?.();}};const choose=(i=0)=>{assert.ok(dialog?.choices,'Expected an explicit story choice');const d=dialog;dialog=null;d.choices[i].action();finish();};const use=o=>{assert.ok(o,'Missing authored object');w.interact(o);finish();};finish();return{w,finish,choose,use,get dialog(){return dialog;}};}
export function earnOpening(){const h=flow(),w=h.w;h.use(w.objects().find(o=>o.type==='npc'));h.use(w.objects().find(o=>o.type==='portal'));h.use(w.objects().find(o=>o.type==='puzzle'&&o.bit===0));h.choose();h.use(w.objects().find(o=>o.type==='puzzle'&&o.bit===1));h.choose();assert.ok(h.dialog?.choices);h.choose();h.use(w.objects().find(o=>o.type==='portal'&&o.to==='workshop'));h.use(w.objects().find(o=>o.type==='cache'&&o.bit===1));h.use(w.objects().find(o=>o.type==='puzzle'&&o.bit===3));h.choose();h.use(w.objects().find(o=>o.type==='portal'&&o.to==='security'));h.use(w.objects().find(o=>o.storyEvent==='iona'));h.choose();return h;}
